const input = $input.first();
const json = (input && input.json) || {};
const body = json.body || json;

let triggerSource = 'mattermost';
try {
  if ($('Webhook Trigger (sm-standup)').first()) {
    triggerSource = 'webhook';
  }
} catch (e) {
  triggerSource = 'mattermost';
}

const baseUrl = (body.baseUrl || json.baseUrl || ($env && $env.ATLASSIAN_BASE_URL) || 'https://entrade.atlassian.net').replace(/\/+$/, '');
const email = ($env && $env.ATLASSIAN_EMAIL) || '';
const token = ($env && $env.ATLASSIAN_API_TOKEN) || '';
const authHeader = 'Basic ' + Buffer.from(`${email}:${token}`).toString('base64');

// Migration Atlassian CHANGE-2046: /rest/api/3/search?jql= bị xóa (HTTP 410)
// Dùng POST /rest/api/3/search/jql với body JSON thay vì GET query string
const searchUrl = `${baseUrl}/rest/api/3/search/jql`;
const searchMethod = 'POST';
const searchBody = {
  jql: 'sprint in openSprints() AND statusCategory != Done',
  fields: ['summary', 'status', 'assignee', 'priority', 'updated', 'customfield_10020', 'customfield_10016'],
  maxResults: 100
};

return [{
  json: {
    baseUrl,
    authHeader,
    searchUrl,
    searchMethod,
    searchBody,
    _triggerSource: triggerSource
  }
}];

const input = $input.first();
const json = (input && input.json) || {};

// Fix: Lấy triggerSource từ Prepare node (đã detect đúng), không detect lại
const prepNode = $('Prepare Standup Request').first()?.json || {};
const triggerSource = prepNode._triggerSource || 'cron';

// Xử lý lỗi Jira API
if (json.error || json.errorMessages || (json.message && !json.issues)) {
  const errMsg = (json.errorMessages && json.errorMessages.join(', ')) ||
                 (json.error && (json.error.message || json.error.description)) ||
                 json.message || 'Không thể kết nối đến Jira Search API';
  return [{
    json: {
      isError: true,
      error: errMsg,
      reportText: `🚨 **[Lỗi Báo Cáo Daily Standup]** Không thể lấy danh sách Sprint đang mở:\n> ${errMsg}\n\n*Gợi ý: Kiểm tra cấu hình ATLASSIAN_BASE_URL, ATLASSIAN_EMAIL và API Token trong file .env.*`,
      totalIssues: 0, stuckCount: 0, _triggerSource: triggerSource
    }
  }];
}

// Phân tích dữ liệu Sprint
const issues = json.issues || [];
const now = new Date();
const stuckIssues = [];
const assigneeWorkload = {};

// Lấy sprint name từ customfield_10020 (issue đầu tiên)
let sprintName = 'Sprint đang mở';
try {
  const firstSprint = issues[0]?.fields?.customfield_10020;
  if (Array.isArray(firstSprint) && firstSprint.length > 0) {
    const activeSprint = firstSprint.find(s => s.state === 'active') || firstSprint[0];
    sprintName = activeSprint.name || sprintName;
  }
} catch (_) {}

let totalSP = 0;

for (const issue of issues) {
  const f = issue.fields;
  const assignee = f.assignee ? f.assignee.displayName : 'Chưa phân bổ';
  const sp = parseFloat(f.customfield_10016 || 0);
  const statusName = (f.status && f.status.name) || '';
  const isInProgress = /in progress|doing|dev|review/i.test(statusName);

  if (!assigneeWorkload[assignee]) {
    assigneeWorkload[assignee] = { count: 0, sp: 0, inProgress: 0 };
  }
  assigneeWorkload[assignee].count++;
  assigneeWorkload[assignee].sp += sp;
  if (isInProgress) assigneeWorkload[assignee].inProgress++;
  totalSP += sp;

  // Kiểm tra ticket bị kẹt > 3 ngày
  const updated = new Date(f.updated);
  const diffDays = (now - updated) / (1000 * 60 * 60 * 24);
  if (diffDays >= 3) {
    stuckIssues.push({
      key: issue.key, summary: f.summary,
      assignee, status: statusName,
      stuckDays: Math.round(diffDays), sp
    });
  }
}

const dateStr = now.toISOString().split('T')[0];
let reportText = `### ☀️ BÁO CÁO DAILY STANDUP (${dateStr}) — ${sprintName}\n`;
reportText += `- **Tổng task đang mở:** ${issues.length} issues`;
if (totalSP > 0) reportText += ` | **Tổng SP In-Sprint:** ${totalSP} SP`;
reportText += `\n- **Cảnh báo task bị treo (>3 ngày):** ${stuckIssues.length} issues\n\n`;

// Render bảng workload balance
const workloadEntries = Object.entries(assigneeWorkload).sort((a, b) => b[1].sp - a[1].sp);
if (workloadEntries.length > 0) {
  reportText += `#### 📊 Bảng Cân Bằng Tải (Workload Balance):\n`;
  reportText += `| 👤 Dev | Issues | SP | In Progress | Trạng thái |\n`;
  reportText += `| :--- | :---: | :---: | :---: | :--- |\n`;
  for (const [name, data] of workloadEntries) {
    const status = data.sp > 15 ? '⚠️ Quá tải' : (data.sp > 8 ? '🟡 Đồng đều' : '🟢 Bình thường');
    reportText += `| **${name}** | ${data.count} | **${data.sp}** SP | ${data.inProgress} | ${status} |\n`;
  }
  reportText += '\n';
}

if (stuckIssues.length > 0) {
  reportText += `#### 🚨 Danh sách Task bị tắc nghẽn (Impediments):\n`;
  for (const s of stuckIssues) {
    const spStr = s.sp > 0 ? ` | ${s.sp} SP` : '';
    reportText += `- **[${s.key}]** ${s.summary} (👤 ${s.assignee} | ⏳ ${s.stuckDays} ngày${spStr})\n`;
  }
}

return [{
  json: {
    isError: false,
    reportText,
    totalIssues: issues.length,
    totalSP,
    stuckCount: stuckIssues.length,
    sprintName,
    _triggerSource: triggerSource
  }
}];
